setupIonicReact({mode:'md',animated:false});
type Tab='Home'|'Library'|'Discover'|'Activity';
type Route={tab:Tab;settings:boolean;plugin:string|null;internal?:string};
type Appearance={theme:'system'|'light'|'dark';textScale:number};
type Activity={id:string;time:string;type:string;plugin?:string;message:string};
type Host=Awaited<ReturnType<typeof createPluginHost>>;
type RuntimeState={label:string;mode:string;state:string};
type Review={pkg:VerifiedPackage;grants:string[];update:boolean};
type PendingConfirmation={title:string;description:string;confirmLabel:string;action:()=>Promise<void>;allowDiscard?:boolean;discard?:()=>Promise<void>};
type BindingRequest={consumer:string;title:string;resolve:(approved:boolean)=>void};
type Task={plugin:string;name:string;runId:string;prompt:string;answer:string;model:string;cursor:number;state:'running'|'partial'|'completed'|'cancelled'|'failed';startedAt?:string};
type InstallPrompt=Event&{prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>};
function isInstallPrompt(event:Event):event is InstallPrompt{return 'prompt' in event&&typeof event.prompt==='function'&&'userChoice' in event&&event.userChoice instanceof Promise;}
const ajv=new Ajv({strict:true});
const appearanceValid=ajv.compile<Appearance>({type:'object',additionalProperties:false,required:['theme','textScale'],properties:{theme:{enum:['system','light','dark']},textScale:{type:'number',minimum:1,maximum:2}}});
const routeValid=ajv.compile<Route>({type:'object',additionalProperties:false,required:['tab','settings','plugin'],properties:{tab:{enum:['Home','Library','Discover','Activity']},settings:{type:'boolean'},plugin:{type:['string','null']},internal:{type:'string',pattern:'^[a-z0-9/-]{1,120}$'}}});
const taskValid=ajv.compile<Omit<Task,'plugin'|'name'>>({type:'object',additionalProperties:false,required:['runId','prompt','answer','model','cursor','state'],properties:{runId:{type:'string',maxLength:240},prompt:{type:'string',maxLength:131072},answer:{type:'string',maxLength:131072},model:{type:'string',maxLength:240},cursor:{type:'integer',minimum:0},state:{enum:['running','partial','completed','cancelled','failed']},startedAt:{type:'string',maxLength:40}}});
const rootsValid=ajv.compile<TrustRoot[]>({type:'array',maxItems:16,items:{type:'object',additionalProperties:false,required:['keyId','publicKey','publisherIdentity','policyVersion'],properties:{keyId:{type:'string'},publicKey:{type:'object'},publisherIdentity:{type:'string'},policyVersion:{type:'string'},demoOnly:{type:'boolean'}}}});
const runtimeValid=ajv.compile<RuntimeState>({type:'object',required:['label','mode','state'],properties:{label:{type:'string'},mode:{type:'string'},state:{type:'string'}}});
const activityValid=ajv.compile<Activity[]>({type:'array',maxItems:100,items:{type:'object',additionalProperties:false,required:['id','time','type','message'],properties:{id:{type:'string',maxLength:80},time:{type:'string',maxLength:40},type:{type:'string',maxLength:100},plugin:{type:'string',maxLength:240},message:{type:'string',maxLength:1000}}}});
const defaults:Route={tab:'Home',settings:false,plugin:null};
function reason(error:unknown):string {return error instanceof Error?error.message:'Operation failed';}
function download(name:string,value:unknown):void {
  const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));
  const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function permissionText(permission:Permission):string {
  if(permission.capability==='storage.kv')return `Save this app’s data on this device (up to ${Math.round(permission.scope.quotaBytes/1048576)} MiB).`;
  if(permission.capability==='network.http')return `Read the approved feed at ${permission.scope.rules.map(rule=>new URL(rule.origin).hostname).join(', ')}. Requests go through the host broker.`;
  if(permission.capability==='ai.respond')return `Send explicit prompts to your connected runtime: up to ${permission.scope.requestsPerHour} PWACloud requests per hour, ${permission.scope.concurrency} at a time. Provider allowance remains unknown. You can stop tasks and revoke access.`;
  return 'Read a Notebook document you select and approve once. No access to other notes.';
}
async function runtimeMutation(path:string,method:'POST'|'DELETE',body?:unknown):Promise<unknown>{
  const session=await fetch('/v1/session',{credentials:'same-origin'});if(!session.ok)throw new Error('No authorized runtime app session.');
  const value:unknown=await session.json();if(typeof value!=='object'||value===null||!('csrfToken' in value)||typeof value.csrfToken!=='string')throw new Error('Invalid runtime session');
  const response=await fetch(path,{method,credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':value.csrfToken},...(body===undefined?{}:{body:JSON.stringify(body)})});
  const result:unknown=await response.json();if(!response.ok)throw new Error('The runtime denied this operation. Review its authorization and connection state.');return result;
}

function App(){
  const [route,setRoute]=useState<Route>(defaults);
  const [host,setHost]=useState<Host|null>(null);
  const [storage,setStorage]=useState<PluginStorage|null>(null);
  const [roots,setRoots]=useState<TrustRoot[]>([]);
  const [catalogue,setCatalogue]=useState<Catalogue|null>(null);
  const [installed,setInstalled]=useState<InstalledPlugin[]>([]);
  const [status,setStatus]=useState('Opening your local workspace…');
  const [failure,setFailure]=useState('');
  const [online,setOnline]=useState(navigator.onLine);
  const [appearance,setAppearance]=useState<Appearance>({theme:'system',textScale:1});
  const [runtime,setRuntime]=useState<RuntimeState>({mode:'unconnected',state:'unavailable',label:'AI not connected'});
  const [models,setModels]=useState<{slug:string;displayName:string}[]>([]);
  const [searches,setSearches]=useState<Record<Tab,string>>({Home:'',Library:'',Discover:'',Activity:''});
  const search=searches[route.tab];
  const setSearch=(value:string)=>setSearches(previous=>({...previous,[route.tab]:value}));
  const [category,setCategory]=useState('All');
  const [repository,setRepository]=useState('');
  const [review,setReview]=useState<Review|null>(null);
  const [installStep,setInstallStep]=useState<'Resolve'|'Review'|'Download'|'Ready'|null>(null);
  const [busy,setBusy]=useState(false);
  const [manage,setManage]=useState<InstalledPlugin|null>(null);
  const [confirmation,setConfirmation]=useState<PendingConfirmation|null>(null);
  const [binding,setBinding]=useState<BindingRequest|null>(null);
  const [activities,setActivities]=useState<Activity[]>([]);
  const [update,setUpdate]=useState<ServiceWorkerRegistration|null>(null);
  const [quickNote,setQuickNote]=useState('');
  const [quickDirty,setQuickDirty]=useState(false);
  const savedQuickNote=useRef('');
  const [welcome,setWelcome]=useState(true);
  const [retainData,setRetainData]=useState(true);
  const [suspended,setSuspended]=useState(false);
  const [pins,setPins]=useState<string[]>([]);
  const [tasks,setTasks]=useState<Task[]>([]);
  const [taskDetail,setTaskDetail]=useState<Task|null>(null);
  const [installPrompt,setInstallPrompt]=useState<InstallPrompt|null>(null);
  const frameArea=useRef<HTMLDivElement>(null);
  const frameSession=useRef<FrameSession|null>(null);
  const content=useRef<HTMLElement>(null);
  const scrollPositions=useRef(new Map<string,number>());
  const tabRoutes=useRef<Record<Tab,Route>>({Home:defaults,Library:{tab:'Library',settings:false,plugin:null},Discover:{tab:'Discover',settings:false,plugin:null},Activity:{tab:'Activity',settings:false,plugin:null}});
  const abort=useRef<AbortController|null>(null);
  const routeRef=useRef(route);routeRef.current=route;
  const storeRef=useRef<PluginStorage|null>(null);
  const activityRef=useRef<Activity[]>([]);
  const activityWrites=useRef(Promise.resolve());

  const record=useCallback((event:{type:string;plugin?:string;message:string})=>{
    const value:Activity={...event,id:crypto.randomUUID(),time:new Date().toISOString()};
    const next=[value,...activityRef.current].slice(0,100);activityRef.current=next;setActivities(next);
    if(storeRef.current){const db=storeRef.current;activityWrites.current=activityWrites.current.catch(()=>undefined).then(()=>db.put('host','activity',next));void activityWrites.current.catch(error=>setFailure(`Activity could not be saved: ${reason(error)}`));}
  },[]);
  const refresh=useCallback(async()=>{if(host)setInstalled(await host.list());},[host]);
  const navigate=useCallback((next:Route,push=true)=>{
    const previous=routeRef.current;
    if(content.current)scrollPositions.current.set(JSON.stringify(previous),content.current.scrollTop);
    if(!previous.settings)tabRoutes.current[previous.tab]=previous;
    if(!next.settings)tabRoutes.current[next.tab]=next;
    if(push)history.pushState(next,'',next.plugin?`/#plugin/${encodeURIComponent(next.plugin)}`:next.settings?'/#settings':`/#${next.tab.toLowerCase()}`);
    routeRef.current=next;setRoute(next);setManage(null);if(next.plugin&&previous.plugin!==next.plugin)setSuspended(false);
  },[]);
  const refreshTasks=useCallback(async()=>{if(!storage)return [];const next:Task[]=[];for(const item of installed){const value=await storage.get(item.manifest.id,'notes/ai');if(taskValid(value))next.push({...value,plugin:item.manifest.id,name:item.manifest.name});}setTasks(next);return next;},[storage,installed]);
  const requestLeave=useCallback(async(next:Route,push=true)=>{
    const current=routeRef.current;
    if(!current.plugin&&current.tab==='Home'&&!current.settings&&quickDirty&&storage){if(!push)history.pushState(current,'',`/#${current.tab.toLowerCase()}`);setConfirmation({title:'Unsaved quick note',description:'Save this note on your device, discard this edit, or keep writing.',confirmLabel:'Save and leave',allowDiscard:true,action:async()=>{await storage.put('host','quick-note',quickNote);savedQuickNote.current=quickNote;setQuickDirty(false);setStatus('Quick note saved on this device');navigate(next);setConfirmation(null);},discard:async()=>{setQuickNote(savedQuickNote.current);setQuickDirty(false);setStatus('Quick note edit discarded');navigate(next);setConfirmation(null);}});return;}
    if(current.plugin&&storage){
      const checkpoint=await storage.get(current.plugin,'host/checkpoint');
      if(typeof checkpoint==='object'&&checkpoint!==null&&'dirty' in checkpoint&&checkpoint.dirty===true){
        if(!push)history.pushState(current,'',current.plugin?`/#plugin/${encodeURIComponent(current.plugin)}`:`/#${current.tab.toLowerCase()}`);
        setConfirmation({title:'Unsaved changes',description:'Wait for the app to save, discard the current unsaved changes, or stay in the editor.',confirmLabel:'Save and leave',allowDiscard:true,action:async()=>{await new Promise<void>(resolve=>setTimeout(resolve,400));const saved=await storage.get(current.plugin??'','host/checkpoint');if(typeof saved==='object'&&saved!==null&&'dirty' in saved&&saved.dirty===false){navigate(next);setConfirmation(null);}else throw new Error('The app has not saved. Stay in the editor and resolve the storage error.');},discard:async()=>{if(current.plugin){const install=await storage.getInstall(current.plugin);await storage.put(current.plugin,'host/checkpoint',{dirty:false},install?.manifest.permissions.find(permission=>permission.capability==='storage.kv')?.scope.quotaBytes??262144);}navigate(next);setConfirmation(null);}});return;
      }
    }
    navigate(next,push);
  },[storage,navigate,quickDirty,quickNote]);

  useEffect(()=>{
    let active=true;let db:PluginStorage|null=null;
    let removeWorkerListeners=()=>{};
    void (async()=>{
      db=await PluginStorage.open();
      storeRef.current=db;
      const preference=await db.get('host','appearance');if(appearanceValid(preference))setAppearance(preference);
      const note=await db.get('host','quick-note');if(typeof note==='string'){savedQuickNote.current=note;setQuickNote(note);}
      const started=await db.get('host','started');setWelcome(started!==true);
      const savedActivity=await db.get('host','activity');if(activityValid(savedActivity)){activityRef.current=savedActivity;setActivities(savedActivity);}
      const savedPins=await db.get('host','pinned-apps');if(Array.isArray(savedPins)&&savedPins.length<=100&&savedPins.every((value:unknown)=>typeof value==='string'&&value.length<=240))setPins(savedPins);
      const savedNavigation=await db.get('host','navigation');const savedTabs=typeof savedNavigation==='object'&&savedNavigation!==null?Reflect.get(savedNavigation,'tabs'):undefined;const savedRoute:unknown=typeof savedNavigation==='object'&&savedNavigation!==null?Reflect.get(savedNavigation,'route'):undefined;if(typeof savedTabs==='object'&&savedTabs!==null){for(const tab of ['Home','Library','Discover','Activity'] as const){const value=Reflect.get(savedTabs,tab);if(routeValid(value)&&value.tab===tab&&!value.settings)tabRoutes.current[tab]=value;}}
      let trust:TrustRoot[]=[];
      const cachedTrust=await db.get('host','trust-roots');if(rootsValid(cachedTrust))trust=cachedTrust;
      try{let response=await fetch('/v1/trust',{signal:AbortSignal.timeout(5000)});if(response.status===401){const bootstrap=await fetch('/v1/session/local',{method:'POST',headers:{'content-type':'application/json'},body:'{}',credentials:'same-origin',signal:AbortSignal.timeout(5000)});if(bootstrap.ok)response=await fetch('/v1/trust',{signal:AbortSignal.timeout(5000)});}if(response.ok){const value:unknown=await response.json();if(!rootsValid(value))throw new Error('Invalid package trust metadata');trust=value;await db.put('host','trust-roots',trust);}else throw new Error('Runtime public verification keys are unavailable.');}catch(error){setStatus(`Local editing is available. Using previously cached public trust metadata: ${reason(error)}`);}
      try{
        const responses=await Promise.all([fetch('/fixtures/catalogue.json',{signal:AbortSignal.timeout(5000)}),fetch('/fixtures/catalogue.sig',{signal:AbortSignal.timeout(5000)})]);
        if(!responses[0]?.ok||!responses[1]?.ok)throw new Error('Catalogue unavailable');
        const bytes=new Uint8Array(await responses[0].arrayBuffer()),signature=new Uint8Array(await responses[1].arrayBuffer());
        const verified=await verifyCatalogue(bytes,signature,trust,{allowDemo:true});setCatalogue(verified);await db.put('host','catalogue-cache',{bytes:Array.from(bytes),signature:Array.from(signature)});
      }catch(error){
        const cached=await db.get('host','catalogue-cache');
        if(typeof cached==='object'&&cached!==null&&'bytes' in cached&&Array.isArray(cached.bytes)&&cached.bytes.every((byte:unknown)=>typeof byte==='number'&&Number.isInteger(byte)&&byte>=0&&byte<=255)&&'signature' in cached&&Array.isArray(cached.signature)&&cached.signature.length===64&&cached.signature.every((byte:unknown)=>typeof byte==='number'&&Number.isInteger(byte)&&byte>=0&&byte<=255)){
          try{setCatalogue(await verifyCatalogue(Uint8Array.from(cached.bytes),Uint8Array.from(cached.signature),trust,{allowDemo:true}));}catch(cachedError){setFailure(`Cached catalogue is not usable: ${reason(cachedError)}`);}
        }else setStatus(`Package catalogue unavailable: ${reason(error)}`);
      }
      const localStorage=db;
      const transport=createHttpAiTransport(async()=>{
        let response=await fetch('/v1/session',{credentials:'same-origin'});
        if(response.status===401){const bootstrap=await fetch('/v1/session/local',{method:'POST',headers:{'content-type':'application/json'},body:'{}',credentials:'same-origin'});if(bootstrap.ok)response=await fetch('/v1/session',{credentials:'same-origin'});}
        if(!response.ok)throw new Error('Connect an authorized personal runtime or explicitly start demo AI in Settings.');
        const value:unknown=await response.json();
        if(typeof value!=='object'||value===null||!('csrfToken' in value)||typeof value.csrfToken!=='string')throw new Error('Invalid runtime session');
        return value.csrfToken;
      },db);
      const controller=await createPluginHost({storage:db,registries:{resolve:(repo,signal)=>new RegistryClient({roots:trust,transport:async(repository,abortSignal)=>{const response=await fetch(`/v1/registry/resolve?repository=${encodeURIComponent(repository)}`,{credentials:'same-origin',signal:abortSignal});if(!response.ok)throw new Error('Repository resolution or signature verification failed.');const packet:unknown=await response.json();const keys=await fetch('/v1/trust',{credentials:'same-origin',signal:abortSignal});if(!keys.ok)throw new Error('Runtime verification keys could not be refreshed.');const rawKeys:unknown=await keys.json();if(!rootsValid(rawKeys))throw new Error('Invalid runtime verification keys.');trust.splice(0,trust.length,...rawKeys);setRoots([...trust]);await localStorage.put('host','trust-roots',trust);return packet;}}).resolveRepository(repo,signal)},aiTransport:transport,network:transport.network,diagnostics:record,onNavigate:(plugin,internal)=>{if(routeRef.current.plugin===plugin&&routeRef.current.internal!==internal)navigate({...routeRef.current,internal});},onBindingRequest:async(consumer,provider,key)=>{
        const selected=await localStorage.get(provider,key);
        if(typeof selected!=='object'||selected===null||!('title' in selected)||typeof selected.title!=='string')return false;
        const title=selected.title;
        return new Promise<boolean>(resolve=>setBinding({consumer,title,resolve}));
      }});
      if(!active)return;
      await controller.recover();const available=await controller.list();setStorage(db);setRoots(trust);setHost(controller);setInstalled(available);setStatus('Local workspace ready');
      let restored:Route=routeValid(history.state)?history.state:routeValid(savedRoute)?savedRoute:defaults;if(restored.plugin&&!available.some(item=>item.manifest.id===restored.plugin&&item.enabled))restored={tab:'Library',settings:false,plugin:null};
      navigate(restored,false);history.replaceState(restored,'',restored.plugin?`/#plugin/${encodeURIComponent(restored.plugin)}`:restored.settings?'/#settings':`/#${restored.tab.toLowerCase()}`);
    })().catch(error=>setFailure(`Workspace unavailable: ${reason(error)}`));
    const checkConnection=()=>{if(!navigator.onLine){setOnline(false);return;}void fetch('/health',{cache:'no-store',signal:AbortSignal.timeout(3000)}).then(response=>{if(active)setOnline(response.ok);}).catch(()=>{if(active)setOnline(false);});};
    const onlineChange=()=>checkConnection();window.addEventListener('online',onlineChange);window.addEventListener('offline',onlineChange);checkConnection();
    let visualResize:(()=>void)|undefined;
    if(window.visualViewport){visualResize=()=>document.documentElement.style.setProperty('--keyboard-height',`${Math.max(0,window.innerHeight-(window.visualViewport?.height??window.innerHeight))}px`);window.visualViewport.addEventListener('resize',visualResize);visualResize();}
    if('serviceWorker' in navigator&&window.isSecureContext){void navigator.serviceWorker.register('/sw.js').then(registration=>{
      if(!active)return;
      const removals=new Set<()=>void>();
      const checkWaiting=()=>{if(active&&registration.waiting&&navigator.serviceWorker.controller)setUpdate(registration);};
      const watchInstalling=()=>{
        const worker=registration.installing;if(!worker)return;
        const changed=()=>{if(active&&worker.state==='installed'&&navigator.serviceWorker.controller)setUpdate(registration);if(worker.state==='installed'||worker.state==='redundant'){remove();checkWaiting();}};
        const remove=()=>{worker.removeEventListener('statechange',changed);removals.delete(remove);};
        removals.add(remove);worker.addEventListener('statechange',changed);changed();
      };
      registration.addEventListener('updatefound',watchInstalling);navigator.serviceWorker.addEventListener('controllerchange',checkWaiting);checkWaiting();watchInstalling();
      removeWorkerListeners=()=>{registration.removeEventListener('updatefound',watchInstalling);navigator.serviceWorker.removeEventListener('controllerchange',checkWaiting);for(const remove of removals)remove();};
    }).catch(error=>record({type:'offline-unavailable',message:reason(error)}));}
    return()=>{active=false;removeWorkerListeners();storeRef.current=null;db?.close();frameSession.current?.close();window.removeEventListener('online',onlineChange);window.removeEventListener('offline',onlineChange);if(visualResize)window.visualViewport?.removeEventListener('resize',visualResize);};
  },[record,navigate]);
  useEffect(()=>{
    const back=(event:PopStateEvent)=>{
      if(review||manage||confirmation||binding||taskDetail){const current=routeRef.current;history.pushState(current,'',current.plugin?`/#plugin/${encodeURIComponent(current.plugin)}`:current.settings?'/#settings':`/#${current.tab.toLowerCase()}`);if(binding){binding.resolve(false);setBinding(null);}else if(confirmation)setConfirmation(null);else if(manage)setManage(null);else if(taskDetail)setTaskDetail(null);else{setReview(null);setInstallStep(null);}return;}
      void requestLeave(routeValid(event.state)?event.state:defaults,false).catch(error=>setFailure(reason(error)));
    };
    window.addEventListener('popstate',back);return()=>window.removeEventListener('popstate',back);
  },[review,manage,confirmation,binding,taskDetail,requestLeave]);
  useEffect(()=>{document.documentElement.dataset.theme=appearance.theme;document.documentElement.style.fontSize=`${16*appearance.textScale}px`;if(storage)void storage.put('host','appearance',appearance).catch(error=>setFailure(reason(error)));},[appearance,storage]);
  useEffect(()=>{const supported=(event:Event)=>{if(isInstallPrompt(event)){event.preventDefault();setInstallPrompt(event);}};const installed=()=>setInstallPrompt(null);window.addEventListener('beforeinstallprompt',supported);window.addEventListener('appinstalled',installed);return()=>{window.removeEventListener('beforeinstallprompt',supported);window.removeEventListener('appinstalled',installed);};},[]);
  useEffect(()=>{if(content.current)content.current.scrollTop=scrollPositions.current.get(JSON.stringify(route))??0;if(storage)void storage.put('host','navigation',{route,tabs:tabRoutes.current}).catch(error=>setFailure(`Navigation could not be saved: ${reason(error)}`));},[route,storage]);
  useEffect(()=>{if(!route.plugin)void refreshTasks().catch(error=>setFailure(`Task checkpoints unavailable: ${reason(error)}`));},[refreshTasks,route.tab,route.plugin]);
  useEffect(()=>{
    if(!host||!route.plugin||!frameArea.current||suspended){frameSession.current?.close();frameSession.current=null;return;}
    let active=true;
    void host.mount(frameArea.current,route.plugin).then(session=>{if(!active){session.close();return;}frameSession.current=session;session.send({type:'host.context',theme:appearance.theme,textScale:appearance.textScale,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,viewport:{width:frameArea.current?.clientWidth??360,height:frameArea.current?.clientHeight??600},models});session.send({type:'host.navigation',route:routeRef.current.internal??'home'});record({type:'opened',plugin:route.plugin??undefined,message:'Opened isolated app'});}).catch(error=>setFailure(`Cannot open app: ${reason(error)}`));
    return()=>{active=false;frameSession.current?.close();frameSession.current=null;};
  },[route.plugin,host,record,suspended]);
  useEffect(()=>{frameSession.current?.send({type:'host.navigation',route:route.internal??'home'});},[route.internal]);
  useEffect(()=>{
    if(!host)return;
    const suspend=()=>{if(document.visibilityState==='hidden'){host.suspend();frameSession.current=null;if(routeRef.current.plugin)setSuspended(true);}};
    document.addEventListener('visibilitychange',suspend);window.addEventListener('pagehide',suspend);
    return()=>{document.removeEventListener('visibilitychange',suspend);window.removeEventListener('pagehide',suspend);};
  },[host]);
  useEffect(()=>{frameSession.current?.send({type:'host.context',theme:appearance.theme,textScale:appearance.textScale,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,models});},[models,appearance]);

  const installFixture=async(id:string)=>{
    if(!host)return;setBusy(true);setFailure('');setInstallStep('Resolve');abort.current=new AbortController();
    try{const pkg=await loadFixture(id,roots,abort.current.signal);setReview({pkg,grants:pkg.manifest.permissions.filter(permission=>permission.required).map(permission=>permission.id),update:installed.some(item=>item.manifest.id===pkg.manifest.id)});setInstallStep('Review');}
    catch(error){setFailure(`Resolve failed: ${reason(error)}`);setInstallStep(null);}finally{setBusy(false);}
  };
  const resolve=async()=>{
    if(!host)return;setBusy(true);setFailure('');setInstallStep('Resolve');abort.current=new AbortController();
    try{const pkg=await host.resolve(repository,abort.current.signal);setReview({pkg,grants:pkg.manifest.permissions.filter(permission=>permission.required).map(permission=>permission.id),update:installed.some(item=>item.manifest.id===pkg.manifest.id)});setInstallStep('Review');}
    catch(error){setFailure(`Resolve failed: ${reason(error)}`);setInstallStep(null);}finally{setBusy(false);}
  };
  const install=async()=>{
    if(!host||!review)return;setBusy(true);setFailure('');setInstallStep('Download');const cancellation=new AbortController();abort.current=cancellation;
    try{if(review.update)await host.update(review.pkg,review.grants,cancellation.signal);else await host.install(review.pkg,review.grants,cancellation.signal);await refresh();setInstallStep('Ready');record({type:'installed',plugin:review.pkg.manifest.id,message:`${review.pkg.manifest.name} ${review.pkg.manifest.version} installed from verified package bytes`});}
    catch(error){if(cancellation.signal.aborted){setStatus('Installation cancelled. Existing installed version is retained.');setInstallStep(null);}else{setFailure(`Install failed: ${reason(error)}`);setInstallStep('Review');}}finally{setBusy(false);}
  };
  const cancelInstall=()=>{abort.current?.abort();setReview(null);setInstallStep(null);setBusy(false);};
  const quickSave=async()=>{if(!storage)return;try{await storage.put('host','quick-note',quickNote);savedQuickNote.current=quickNote;setQuickDirty(false);setStatus('Quick note saved on this device');await storage.put('host','started',true);setWelcome(false);record({type:'saved',message:'Quick note saved locally'});}catch(error){setFailure(reason(error));}};
  const getRuntimeStatus=async()=>{try{const response=await fetch('/v1/provider/status',{credentials:'same-origin'});if(!response.ok)throw new Error(`Runtime returned ${response.status}`);const value:unknown=await response.json();if(!runtimeValid(value))throw new Error('Invalid runtime status');setRuntime(value);const catalogue=await fetch('/v1/provider/models',{credentials:'same-origin'});if(catalogue.ok){const data:unknown=await catalogue.json();if(Array.isArray(data)){const entries=data.filter((item):item is {slug:string;displayName:string}=>typeof item==='object'&&item!==null&&'slug'in item&&typeof item.slug==='string'&&'displayName'in item&&typeof item.displayName==='string');setModels(entries);}}return value;}catch(error){setRuntime({mode:'unconnected',state:'unavailable',label:'Personal runtime unavailable'});setFailure(reason(error));}};
  const tryDemo=async()=>{try{const response=await fetch('/v1/session/local',{method:'POST',headers:{'content-type':'application/json'},body:'{}',credentials:'same-origin'});if(!response.ok)throw new Error('The local runtime did not authorize a demo session');const current=await getRuntimeStatus();if(current?.mode!=='demo')throw new Error('This runtime is configured for real authorization. Connect ChatGPT on its computer; a local app session is not demo inference.');setStatus('Synthetic demo session connected. This does not sign in to ChatGPT.');record({type:'demo-connected',message:'Explicit synthetic demo session connected'});}catch(error){setFailure(reason(error));}};
  const connectChatGpt=async()=>{try{const value=await runtimeMutation('/v1/provider/connect','POST',{});if(typeof value!=='object'||value===null||!('authorizationUrl' in value)||typeof value.authorizationUrl!=='string')throw new Error('Invalid authorization response');const url=new URL(value.authorizationUrl);if(url.origin!=='https://auth.openai.com'||url.username||url.password)throw new Error('Invalid authorization origin');window.open(url.href,'_blank','noopener,noreferrer');setStatus('Complete the real OpenAI authorization on your runtime computer, then check runtime status. Account identity alone does not grant plugin inference entitlement.');}catch(error){setFailure(reason(error));}};
  const disconnectProvider=()=>setConfirmation({title:'Disconnect ChatGPT provider?',description:'Cancel provider tasks and clear this runtime’s selected provider credentials. Provider revocation will be reported separately from local removal.',confirmLabel:'Disconnect provider',action:async()=>{const value=await runtimeMutation('/v1/provider','DELETE');if(typeof value!=='object'||value===null||!('remoteRevocationConfirmed' in value)||typeof value.remoteRevocationConfirmed!=='boolean')throw new Error('Invalid revocation response');setModels([]);setRuntime({mode:runtime.mode,state:'unavailable',label:'AI not connected'});host?.suspend();setConfirmation(null);setStatus(value.remoteRevocationConfirmed?'Provider disconnected; remote revocation was confirmed.':'Local provider disconnected. Remote provider revocation was not confirmed.');}});
  const signOut=()=>setConfirmation({title:'Sign out of this app session?',description:'Cancel this session’s runtime tasks and revoke its app authority. This does not claim OpenAI provider revocation.',confirmLabel:'Sign out of app session',action:async()=>{const value=await runtimeMutation('/v1/session','DELETE');if(typeof value!=='object'||value===null||!('signedOut' in value)||value.signedOut!==true)throw new Error('Sign-out was not confirmed');setModels([]);setRuntime({mode:'unconnected',state:'unavailable',label:'AI not connected'});host?.suspend();setConfirmation(null);setStatus('App session signed out. Local tool data stays on this device.');}});
  const stopTask=async(task:Task)=>{try{const result=await runtimeMutation(`/v1/runs/${encodeURIComponent(task.runId)}/cancel`,'POST',{});if(typeof result!=='object'||result===null||!('runId' in result)||result.runId!==task.runId||!('state' in result)||typeof result.state!=='string')throw new Error('Invalid runtime cancellation response');if(result.state!=='cancelled'){setStatus(`Runtime task reports ${result.state}. Resume the existing run to retrieve its latest events; the saved output remains partial.`);return;}const checkpoint={runId:task.runId,prompt:task.prompt,answer:task.answer,model:task.model,cursor:task.cursor,state:'cancelled',...(task.startedAt?{startedAt:task.startedAt}:{})};await storage?.put(task.plugin,'notes/ai',checkpoint,installed.find(item=>item.manifest.id===task.plugin)?.manifest.permissions.find(permission=>permission.capability==='storage.kv')?.scope.quotaBytes??1048576);await refreshTasks();setTaskDetail(null);setStatus('Runtime cancellation confirmed. Saved output remains available.');record({type:'ai-cancelled',plugin:task.plugin,message:'Runtime AI task cancelled by the user'});}catch(error){setFailure(`Task cancellation unavailable: ${reason(error)}`);}};
  const togglePin=async(id:string)=>{if(!storage)return;try{const next=pins.includes(id)?pins.filter(value=>value!==id):[...pins,id];await storage.put('host','pinned-apps',next);setPins(next);}catch(error){setFailure(`Pin could not be saved: ${reason(error)}`);}};
  const selected=installed.find(item=>item.manifest.id===route.plugin);
  const activeTask=tasks.find(task=>task.state==='running'||task.state==='partial');
  const recentTool=installed.find(item=>activities.find(event=>event.type==='opened'&&event.plugin)?.plugin===item.manifest.id);
  const useful=installed.length>0||activities.some(event=>event.type==='saved');
  const iosInstall=/iPad|iPhone|iPod/.test(navigator.userAgent)||(/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1);
  const sampleApps=catalogue?searchCatalogue(catalogue).filter(entry=>entry.id.startsWith('dev.stevenbuglione.')&&['notebook','feed-reader','canvas-board'].includes(entry.id.slice('dev.stevenbuglione.'.length))).map(entry=>({id:entry.id.slice('dev.stevenbuglione.'.length),name:entry.title,description:entry.description,category:entry.capabilities.includes('network.http')?'Read':entry.capabilities.includes('services.invoke')?'Create':'Write',offline:entry.offline})):[];
  const filtered=installed.filter(item=>`${item.manifest.name} ${item.manifest.description}`.toLowerCase().includes(search.toLowerCase()));
  const modalOpen=Boolean(review||manage||confirmation||binding||taskDetail);
  return <IonApp><div className={`shell ${route.plugin?'plugin-active':''}`}>
    <header className="header"><div className="brand"><span aria-hidden="true" className="brand-mark">P</span><div><h1>{selected?selected.manifest.name:'PWACloud'}</h1><span className="connection">{runtime.label}</span></div></div><button className="icon-button" onClick={()=>void requestLeave(route.settings?tabRoutes.current[route.tab]:{tab:route.tab,settings:true,plugin:null})} aria-label={route.settings?'Close Settings':'Settings'}>{route.settings?'Close':'Settings'}</button></header>
    {!online&&<div className="offline-banner" role="status">Offline · local tools and saved data remain available</div>}
    {update&&<div className="update-banner"><span>An app update is ready.</span><button onClick={()=>setConfirmation({title:'Apply app update?',description:'Save your work and stop active tasks before reloading. Installed app data stays on this device.',confirmLabel:'Save and reload',action:async()=>{if(quickDirty)throw new Error('Save or discard your quick note before updating.');const currentTasks=await refreshTasks();if(currentTasks.some(task=>task.state==='running'||task.state==='partial'))throw new Error('Resume or stop the existing AI task and save its output before updating.');if(route.plugin&&storage){const value=await storage.get(route.plugin,'host/checkpoint');if(typeof value==='object'&&value!==null&&'dirty' in value&&value.dirty===true)throw new Error('Return to your app and finish saving before applying this update.');}update.waiting?.postMessage({type:'apply-update'});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});}})}>Review update</button></div>}
    <main aria-label="PWACloud workspace" ref={content} className={route.plugin?'content plugin-content':'content'} id="main-content">
      {failure&&<Status error>{failure}<button onClick={()=>setFailure('')}>Dismiss error</button></Status>}
      {route.plugin?<><div className="plugin-chrome"><button onClick={()=>void requestLeave({tab:'Library',settings:false,plugin:null})}>Back to Library</button><button onClick={()=>{if(selected)setManage(selected);}}>Permissions</button><span>Isolated app</span></div>{suspended&&<section className="resume-panel"><h2>App paused</h2><p>Browser suspension closed the app frame and Worker. Resume explicitly to restore saved work. Existing AI runs resume from their saved event cursor when you choose that action.</p><button className="primary" onClick={()=>setSuspended(false)}>Resume app</button></section>}<div className="frame-area" ref={frameArea}/></>:route.settings?<section><h2>Settings</h2><section className="settings-group"><h3>Appearance</h3><label>Color scheme<select value={appearance.theme} onChange={event=>{const theme=event.target.value;if(theme==='system'||theme==='light'||theme==='dark')setAppearance({...appearance,theme});}}><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Text size<select value={appearance.textScale} onChange={event=>setAppearance({...appearance,textScale:Number(event.target.value)})}><option value="1">Standard</option><option value="1.25">Large</option><option value="1.5">Extra large</option><option value="2">200% text</option></select></label></section><section className="settings-group"><h3>Runtime &amp; ChatGPT</h3><p>{runtime.label}: {runtime.state}</p><p>Your personal computer hosts authorized AI requests. Mobile-only ChatGPT sign-in and hosted account storage remain unavailable.</p><div className="actions"><button onClick={()=>void getRuntimeStatus()}>Check my runtime</button>{(runtime.mode==='unconnected'||runtime.mode==='demo')&&<button onClick={()=>void tryDemo()}>Try demo AI</button>}{runtime.mode==='chatgpt-plan-local'&&<button onClick={()=>void connectChatGpt()}>Connect ChatGPT on this computer</button>}<button onClick={disconnectProvider}>Disconnect provider</button><button onClick={signOut}>Sign out app session</button></div><p className="muted">Demo AI is synthetic. An authorized human ChatGPT sign-in and model entitlement are required for real inference. No paid API fallback.</p></section><section className="settings-group"><h3>App permissions</h3>{installed.length?installed.map(item=><button className="list-button" key={item.manifest.id} onClick={()=>setManage(item)}>{item.manifest.name} · {item.grants.length} granted capabilities</button>):<p>No installed apps.</p>}</section><section className="settings-group"><h3>Storage &amp; export</h3><p>Your notes and installed packages are stored in this browser. Export private content only to a location you trust.</p><button onClick={()=>setConfirmation({title:'Export workspace data?',description:'The export includes your private quick note and installed app data. Store it somewhere you trust.',confirmLabel:'Export private data',action:async()=>{if(!host)return;const values=await Promise.all(installed.map(async item=>({plugin:item.manifest.id,data:await host.exportData(item.manifest.id)})));download('pwacloud-private-export.json',{quickNote,apps:values});setConfirmation(null);}})}>Export workspace</button></section><section className="settings-group"><h3>Updates</h3><p>{update?'An update is ready.':'No waiting app update detected.'}</p><button onClick={()=>void navigator.serviceWorker?.getRegistration().then(registration=>registration?.update()).catch(error=>setFailure(reason(error)))}>Check for update</button></section><section className="settings-group"><h3>Privacy</h3><p>App credentials are never delivered to plugins. Installed web UIs run in an opaque-origin frame. A frame does not provide complete outbound-network or CPU isolation.</p></section><section className="settings-group"><h3>Diagnostics</h3><p>Export event types and timestamps. Prompts, document contents, credentials and account identifiers are excluded.</p><button onClick={()=>download('pwacloud-diagnostics.json',{secureContext:window.isSecureContext,online,events:activities.map(item=>({time:item.time,type:item.type})),version:'0.1.0-dev'})}>Export redacted diagnostics</button></section></section>:route.tab==='Home'?<section>{welcome&&<div className="welcome"><p className="eyebrow">YOUR LOCAL WORKSPACE</p><h2>Useful tools.<br/>Your own space.</h2><p>Write, read and create on your phone. Keep local work available without an account.</p><button className="primary" onClick={()=>{setWelcome(false);void storage?.put('host','started',true);}}>Start without an account</button></div>}{useful&&!matchMedia('(display-mode: standalone)').matches&&(installPrompt||iosInstall)&&<section className="section"><h2>Keep this workspace on your Home Screen</h2>{installPrompt?<button onClick={()=>void(async()=>{try{await installPrompt.prompt();const choice=await installPrompt.userChoice;setStatus(choice.outcome==='accepted'?'Browser installation accepted.':'Browser installation dismissed.');setInstallPrompt(null);}catch(error){setFailure(`Browser install prompt unavailable: ${reason(error)}`);}})()}>Install PWACloud</button>:<p>In Safari, open Share, choose Add to Home Screen, then Add. Home Screen installation and keyboard behavior still depend on your device.</p>}</section>}<section className="section"><h2>Quick note</h2><p className="muted">Saved directly on this device, available offline.</p><label>Quick note text<textarea value={quickNote} maxLength={20000} onChange={event=>{setQuickNote(event.target.value);setQuickDirty(true);setStatus('Quick note has unsaved changes');}} placeholder="Capture a thought…"/></label><button className="primary" onClick={()=>void quickSave()}>Save quick note</button></section>{activeTask&&<section className="section task-summary"><h2>Active AI task</h2><p>{activeTask.name} · saved state: {activeTask.state}. The personal runtime may continue while this browser is paused.</p><div className="actions"><button onClick={()=>setTaskDetail(activeTask)}>View active task</button><button onClick={()=>void stopTask(activeTask)}>Stop active task</button></div></section>}{recentTool&&<section className="section"><h2>Recent tool</h2><button onClick={()=>void requestLeave({tab:'Home',settings:false,plugin:recentTool.manifest.id})}>Open most recent tool: {recentTool.manifest.name}</button></section>}{pins.some(id=>installed.some(item=>item.manifest.id===id))&&<section className="section"><h2>Pinned tools</h2>{installed.filter(item=>pins.includes(item.manifest.id)).map(item=><button className="list-button" key={item.manifest.id} onClick={()=>void requestLeave({tab:'Home',settings:false,plugin:item.manifest.id})}>{item.manifest.name}</button>)}</section>}<section className="section"><h2>Your tools</h2>{installed.length?<div className="app-list">{installed.map(item=><button key={item.manifest.id} className="app-row" onClick={()=>void requestLeave({tab:'Home',settings:false,plugin:item.manifest.id})}><span className="app-icon" aria-hidden="true">{item.manifest.name.charAt(0)}</span><span><strong>{item.manifest.name}</strong><span className="muted">{item.state==='paused'?'Paused to save memory':item.manifest.description}</span></span><span aria-hidden="true">→</span></button>)}</div>:<EmptyState title="A place for your first tool"><p>Install Notebook to make rich notes and run local text analysis.</p><button onClick={()=>navigate({tab:'Discover',settings:false,plugin:null})}>Explore apps</button></EmptyState>}</section></section>:route.tab==='Library'?<section><h2>Library</h2><label>Search installed apps<input type="search" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Name or purpose"/></label>{filtered.length?<div className="app-list">{filtered.map(item=><div className="library-row" key={item.manifest.id}><button className="app-row" onClick={()=>navigate({tab:'Library',settings:false,plugin:item.manifest.id})}><span className="app-icon" aria-hidden="true">{item.manifest.name.charAt(0)}</span><span><strong>{item.manifest.name}</strong><span className="muted">{item.manifest.description}</span><span className="state">{item.state==='paused'?'Paused to save memory':item.state}</span></span></button><button aria-label={`Manage ${item.manifest.name}`} className="manage-button" onClick={()=>setManage(item)}>Manage</button></div>)}</div>:<EmptyState title={search?'No matching apps':'Your library is empty'}><p>Find an app in Discover, then review its capabilities before installing.</p><button onClick={()=>navigate({tab:'Discover',settings:false,plugin:null})}>Open Discover</button></EmptyState>}</section>:route.tab==='Discover'?<section><h2>Discover</h2><p className="muted">Built local examples. Fixture signatures prove these bytes; they do not certify app safety or public release provenance.</p><label>Search example apps<input type="search" value={search} onChange={event=>setSearch(event.target.value)}/></label><div className="segments" aria-label="Categories">{['All','Write','Read','Create'].map(value=><button key={value} aria-pressed={category===value} onClick={()=>setCategory(value)}>{value}</button>)}</div><div className="app-list">{sampleApps.filter(app=>(category==='All'||app.category===category)&&`${app.name} ${app.description}`.toLowerCase().includes(search.toLowerCase())).map(app=><div className="catalogue-row" key={app.id}><span className="app-icon" aria-hidden="true">{app.name.charAt(0)}</span><div><h3>{app.name}</h3><p>{app.description}</p><span className="state">{app.id==='feed-reader'?'Feed refresh needs connection':'Local features work offline after install'}</span><button disabled={busy||!roots.length||!online} onClick={()=>void installFixture(app.id)}>Review {app.name}</button></div></div>)}</div><section className="section"><h3>Install from repository</h3><p>Resolve a supported signed release without rebuilding the shell.</p><label>GitHub repository URL<input type="url" autoCapitalize="none" autoCorrect="off" value={repository} onChange={event=>setRepository(event.target.value)} placeholder="https://github.com/owner/repository"/></label><button disabled={busy||!online||!repository} onClick={()=>void resolve()}>Resolve repository</button></section>{installStep==='Resolve'&&<div className="resolve-status"><Status>Resolve · checking repository and package signatures…</Status><button onClick={cancelInstall}>Cancel resolution</button></div>}</section>:<section><h2>Activity</h2><p className="muted">Saved AI task checkpoints and local workspace events. Browser work pauses when this page is suspended; the personal runtime may continue.</p><button onClick={()=>void refreshTasks().catch(error=>setFailure(reason(error)))}>Refresh saved task states</button>{tasks.length>0&&<section className="section"><h3>AI tasks</h3><ol className="activity-list">{tasks.map(task=><li key={task.runId}><strong>{task.name} AI · {task.state}</strong><span>Saved state · {task.model}</span>{task.startedAt&&<time dateTime={task.startedAt}>Started {new Date(task.startedAt).toLocaleString()}</time>}<div className="actions"><button onClick={()=>setTaskDetail(task)}>View {task.name} AI task</button>{['running','partial'].includes(task.state)&&<><button onClick={()=>void stopTask(task)}>Stop {task.name} AI task</button><button onClick={()=>navigate({tab:'Activity',settings:false,plugin:task.plugin,internal:'ai'})}>Resume {task.name} AI task</button></>}</div></li>)}</ol></section>}{activities.length?<ol className="activity-list">{activities.map(item=><li key={item.id}><strong>{item.message}</strong><time dateTime={item.time}>{new Date(item.time).toLocaleTimeString()}</time><span>{item.type}</span></li>)}</ol>:<EmptyState title="No activity yet"><p>Saved notes, installed apps and app lifecycle events appear here.</p></EmptyState>}</section>}
      {!route.plugin&&<Status>{status}</Status>}
    </main>
    {!route.plugin&&<nav className="bottom-nav" aria-label="Main navigation">{(['Home','Library','Discover','Activity'] as const).map(tab=><button key={tab} aria-current={!route.settings&&route.tab===tab?'page':undefined} onClick={()=>void requestLeave(tabRoutes.current[tab])}><span aria-hidden="true">{tab==='Home'?'⌂':tab==='Library'?'▤':tab==='Discover'?'⊕':'◷'}</span>{tab}</button>)}</nav>}
    {review&&<Dialog title={installStep==='Ready'?`${review.pkg.manifest.name} is ready`:`Review ${review.pkg.manifest.name}`} onCancel={cancelInstall}><ol className="steps" aria-label="Installation steps">{['Resolve','Review','Download','Ready'].map(step=><li key={step} aria-current={installStep===step?'step':undefined}>{step}</li>)}</ol>{installStep==='Ready'?<><p>Installed version {review.pkg.manifest.version}. Local package verification passed.</p><div className="actions"><button className="primary" onClick={()=>{const id=review.pkg.manifest.id;cancelInstall();navigate({tab:'Library',settings:false,plugin:id});}}>Open {review.pkg.manifest.name}</button><button onClick={cancelInstall}>Done</button></div></>:<><p>{review.pkg.manifest.description}</p><dl className="metadata"><dt>Repository</dt><dd>{review.pkg.manifest.source.repository}</dd><dt>Publisher identity</dt><dd>{review.pkg.receipt.publisherIdentity}</dd><dt>Version / license</dt><dd>{review.pkg.manifest.version} / {review.pkg.manifest.license}</dd><dt>Package size</dt><dd>{Math.ceil(review.pkg.envelope.archive.bytes/1024)} KiB</dd><dt>Host API</dt><dd>{review.pkg.manifest.hostApi.major}.{review.pkg.manifest.hostApi.minimumMinor}</dd><dt>Isolation</dt><dd>Opaque-origin web frame. Self-navigation and CPU limits remain browser constraints.</dd><dt>Release digest</dt><dd className="digest">{review.pkg.envelope.archive.sha256}</dd></dl>{review.update&&<p className="notice">Update review: recheck every capability. New permissions require a fresh grant; previous package remains available for compatible rollback.</p>}<h3>Capabilities</h3>{review.pkg.manifest.permissions.map(permission=><label className="permission" key={permission.id}><input type="checkbox" checked={review.grants.includes(permission.id)} disabled={permission.required||busy} onChange={event=>setReview({...review,grants:event.target.checked?[...review.grants,permission.id]:review.grants.filter(id=>id!==permission.id)})}/><span><strong>{permission.required?'Required':'Optional'}</strong><span>{permissionText(permission)}</span></span></label>)}<p className="muted">Required device storage enables this app. Optional capabilities can be denied and revoked later.</p><div className="actions"><button className="primary" disabled={busy} onClick={()=>void install()}>{busy?'Downloading…':review.update?'Apply reviewed update':'Install reviewed app'}</button><button onClick={cancelInstall}>Cancel</button></div>{failure&&<Status error>{failure}</Status>}</>}</Dialog>}
    {manage&&<Dialog title={`Manage ${manage.manifest.name}`} onCancel={()=>setManage(null)}><p>Version {manage.manifest.version} · {manage.manifest.license}</p><p className="digest">{manage.digest}</p><button aria-pressed={pins.includes(manage.manifest.id)} onClick={()=>void togglePin(manage.manifest.id)}>{pins.includes(manage.manifest.id)?'Unpin from Home':'Pin to Home'}</button><h3>App permissions</h3>{manage.manifest.permissions.map(permission=><div className="permission-management" key={permission.id}><p>{permissionText(permission)}</p><span>{manage.grants.includes(permission.id)?'Granted':'Denied'}</span>{manage.grants.includes(permission.id)&&<button onClick={()=>{if(permission.required)setConfirmation({title:'Revoke required storage?',description:'The app will stop and cannot save or read data until reinstalled with an explicit grant.',confirmLabel:'Revoke and close',action:async()=>{await host?.revoke(manage.manifest.id,permission.id);await refresh();setManage(null);setConfirmation(null);navigate({tab:'Library',settings:false,plugin:null});}});else void host?.revoke(manage.manifest.id,permission.id).then(async()=>{await refresh();setManage(null);setStatus('Permission revoked. Reopen the app to start a fresh session.');}).catch(error=>setFailure(reason(error)));}}>Revoke {permission.id}</button>}</div>)}<div className="actions"><button onClick={()=>setConfirmation({title:`Export ${manage.manifest.name} data?`,description:'This file contains private app data. Store it somewhere you trust.',confirmLabel:'Export app data',action:async()=>{download(`${manage.manifest.name.toLowerCase().replaceAll(' ','-')}-private-data.json`,await host?.exportData(manage.manifest.id));setConfirmation(null);}})}>Export data</button><button onClick={()=>void host?.rollback(manage.manifest.id).then(async()=>{await refresh();setManage(null);setStatus('Previous compatible version restored.');}).catch(error=>setFailure(`Recovery unavailable: ${reason(error)}`))}>Restore previous version</button></div><label className="permission"><input type="checkbox" checked={retainData} onChange={event=>setRetainData(event.target.checked)}/><span>Keep app data after uninstall</span></label><button className="danger" onClick={()=>setConfirmation({title:`Uninstall ${manage.manifest.name}?`,description:retainData?'App access will be revoked. Saved data will stay on this device for a later reinstall.':'App access will be revoked and its private saved data will be deleted. Export it first if needed.',confirmLabel:'Uninstall app',action:async()=>{await host?.uninstall(manage.manifest.id,!retainData);await refresh();setManage(null);setConfirmation(null);navigate({tab:'Library',settings:false,plugin:null});}})}>Uninstall</button><button onClick={()=>setManage(null)}>Close app management</button></Dialog>}
    {confirmation&&<Dialog title={confirmation.title} onCancel={()=>setConfirmation(null)}><p>{confirmation.description}</p><div className="actions"><button className="primary" onClick={()=>void confirmation.action().catch(error=>setFailure(reason(error)))}>{confirmation.confirmLabel}</button>{confirmation.allowDiscard&&<button className="danger" onClick={()=>void confirmation.discard?.()}>Discard and leave</button>}<button onClick={()=>setConfirmation(null)}>Cancel</button></div>{failure&&<Status error>{failure}</Status>}</Dialog>}
    {binding&&<Dialog title="Allow selected note once?" onCancel={()=>{binding.resolve(false);setBinding(null);}}><p>Allow {installed.find(item=>item.manifest.id===binding.consumer)?.manifest.name??'this app'} to read “{binding.title}” from Notebook once?</p><p className="muted">The approval is scoped to this saved note, app generation and operation. It expires after one use or one minute.</p><div className="actions"><button className="primary" onClick={()=>{binding.resolve(true);setBinding(null);}}>Allow this note once</button><button onClick={()=>{binding.resolve(false);setBinding(null);}}>Deny</button></div></Dialog>}
    {taskDetail&&<Dialog title={`${taskDetail.name} AI task`} onCancel={()=>setTaskDetail(null)}><p>State last saved by the app: {taskDetail.state}. A running or partial checkpoint does not prove the runtime is still executing.</p><p>Model: {taskDetail.model}</p><h3>Sent prompt</h3><pre className="task-output">{taskDetail.prompt}</pre><h3>{taskDetail.state==='completed'?'Saved output':'Saved partial output'}</h3><pre className="task-output">{taskDetail.answer||'No output saved yet.'}</pre><p className="muted">Opening an app joins this saved run only when you choose Resume existing run. It never resubmits a prompt automatically.</p><div className="actions"><button onClick={()=>{navigate({tab:'Activity',settings:false,plugin:taskDetail.plugin,internal:'ai'});setTaskDetail(null);}}>Open existing task in {taskDetail.name}</button>{['running','partial'].includes(taskDetail.state)&&<button onClick={()=>void stopTask(taskDetail)}>Stop existing task</button>}<button onClick={()=>setTaskDetail(null)}>Close task details</button></div></Dialog>}
    {modalOpen&&<span className="sr-only">Host review dialog open</span>}
  </div></IonApp>;
}
const root=document.getElementById('root');if(root)createRoot(root).render(<App/>);
